from collections import OrderedDict as _OD
class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.cap, self.d = capacity, _OD()
    def get(self, k):
        if k not in self.d:
            return None
        self.d.move_to_end(k)
        return self.d[k]
    def put(self, k, v):
        if k in self.d:
            self.d.move_to_end(k)
        self.d[k] = v
        if len(self.d) > self.cap:
            self.d.popitem(last=False)
    def __len__(self):
        return len(self.d)
class _NoRefresh(LRUCache):
    def get(self, k):
        return self.d.get(k)
class _EvictsOnUpdate(LRUCache):
    def put(self, k, v):
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)
        self.d[k] = v
        self.d.move_to_end(k)

