import time as _time
from collections import defaultdict as _dd, deque as _dq
class RateLimiter:
    def __init__(self, limit, window, clock=_time.monotonic):
        self.limit, self.window, self.clock = limit, window, clock
        self.hits = _dd(_dq)
    def _expired(self, age):
        return age >= self.window
    def allow(self, key):
        now, q = self.clock(), self.hits[key]
        while q and self._expired(now - q[0]):
            q.popleft()
        if len(q) < self.limit:
            q.append(now)
            return True
        return False
class _InclusiveEdge(RateLimiter):
    def _expired(self, age):
        return age > self.window
class _IgnoresClock(RateLimiter):
    def __init__(self, limit, window, clock=None):
        super().__init__(limit, window, _time.monotonic)

