import heapq as _hq, itertools as _it
class PriorityQueue:
    def __init__(self):
        self._heap, self._count = [], _it.count()
    def push(self, item, priority):
        _hq.heappush(self._heap, (priority, next(self._count), item))
    def pop(self):
        return _hq.heappop(self._heap)[2]
class _AlphaTies(PriorityQueue):
    def push(self, item, priority):
        _hq.heappush(self._heap, (priority, item, item))
class _PopNone(PriorityQueue):
    def pop(self):
        return _hq.heappop(self._heap)[2] if self._heap else None

